    *{box-sizing:border-box}body{margin:0;background:#f2f4f7;color:var(--ink);font:14px Inter,Segoe UI,Arial,sans-serif}.wrap{max-width:1080px;margin:auto;padding:22px}.top,.card,.machine-toolbar{background:#fff;border:1px solid var(--line);border-radius:12px}.top{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:18px 22px;box-shadow:0 5px 20px #1d2b3a0d}.brand{display:flex;align-items:center;gap:16px}.brand img{width:145px}.brand h1{font-size:22px;margin:0}.brand p{margin:4px 0 0;color:var(--muted);font-size:12px}.actions{display:flex;flex-wrap:wrap;gap:8px}.btn{border:1px solid #ccd3dc;background:#fff;border-radius:7px;min-height:40px;padding:0 15px;font-weight:700;color:#485567;cursor:pointer}.btn.primary{background:var(--red);border-color:var(--red);color:#fff}.btn.good{background:var(--green);border-color:var(--green);color:#fff}.card{margin-top:16px;overflow:hidden}.card-head{padding:14px 18px;background:var(--soft);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}.card-head h2,.card-head h3{font-size:14px;text-transform:uppercase;letter-spacing:.04em;margin:0}.card-body{padding:18px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.field.full{grid-column:1/-1}.field label{display:block;font-size:11px;font-weight:800;text-transform:uppercase;color:#667386;margin-bottom:6px}.field input,.field textarea{width:100%;border:1px solid #ced5de;border-radius:7px;padding:10px 11px;background:#fff}.field input[readonly]{background:#f4f6f8;color:#445366}.field textarea{min-height:76px;resize:vertical}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:720px}th,td{border:1px solid #cfd6df;padding:8px;text-align:left}th{background:#f4f6f8;font-size:11px;text-transform:uppercase}td input{width:100%;border:0;outline:0;padding:3px;background:transparent}.row-btn{border:0;background:none;color:var(--red);font-size:19px;cursor:pointer}.add{margin-top:10px}.hint{font-size:12px;color:var(--muted)}.machine-toolbar{margin-top:16px;padding:16px 18px;display:flex;align-items:center;justify-content:space-between;gap:12px}.machine-toolbar h2{margin:0;font-size:15px}.machine-toolbar p{margin:4px 0 0;color:var(--muted);font-size:12px}.machine-report{margin-top:18px;border:2px solid #cfd8e2;border-radius:14px;background:#fff;overflow:hidden;box-shadow:0 4px 16px #2030400a}.machine-banner{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 18px;background:#eaf0f5;border-bottom:1px solid #cfd8e2}.machine-banner h2{margin:0;font-size:16px;color:#263d52}.machine-banner .remove-machine{color:#a52a32}.machine-report .card{margin:14px;border-radius:9px;box-shadow:none}.machine-report .system-card{border-color:#c9d5e0}.machine-report .system-card .card-body{background:#fbfcfd}.total-row th{background:#eaf0f5}.total-value{font-weight:800;color:#1f4e78}.sig-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:30px;margin-top:20px}.sig{height:65px;border-bottom:1px solid #333;padding-top:44px;font-size:11px;font-style:italic}.calc-guide{margin:18px 0;border:1px solid #cfd8e2;border-radius:10px;background:#f8fafc;overflow:hidden}.calc-guide summary{cursor:pointer;padding:14px 16px;font-weight:800;color:#33475b;background:#eaf0f5}.calc-body{padding:16px}.formula{padding:11px 13px;margin-bottom:12px;border-left:4px solid var(--blue);background:#fff;line-height:1.7}.reference-table{font-size:11px;min-width:760px}.reference-table th,.reference-table td{text-align:center;padding:6px}.reference-table td:first-child,.reference-table td:nth-child(2){text-align:left}.choice{border:2px dashed #d5dae2;text-align:center;padding:24px;border-radius:10px}.choice input{display:none}.saved{display:none;margin-top:12px;padding:10px 14px;border-radius:7px;background:#eaf7ee;color:var(--green);font-weight:700}.saved.show{display:block}.bottom-add{text-align:center;margin:18px 0}.report-count{display:inline-block;background:#fff;border:1px solid #ccd7e1;border-radius:999px;padding:5px 10px;font-size:11px;font-weight:800;color:#52677a}
