  <header class="top">
    <div class="brand"><img src="assets/images/vakharia-airtech-logo.png" alt="Vakharia Airtech"><div><h1>Pre-Commissioning Report</h1><p>One complete report for each outdoor machine</p></div></div>
    <div class="actions"><button class="btn" type="button" onclick="returnToDaily()">Back</button><button class="btn" type="button" onclick="downloadExcel()">Download Excel</button><button class="btn" type="button" onclick="window.print()">Print / Save PDF</button><button class="btn good" type="button" onclick="saveReport()">Save Reports &amp; Return</button></div>
  </header>

  <section class="card client-card">
    <div class="card-head"><h2>Client details</h2><span class="hint">Shared by every machine report</span></div>
    <div class="card-body grid">
      <div class="field"><label>Date of commissioning *</label><input id="date" type="date" required></div>
      <div class="field"><label>Customer name *</label><input id="customer" value="<?= $q('customer') ?>" required></div>
      <div class="field"><label>Contact person</label><input id="contact" placeholder="Name and mobile number"></div>
      <div class="field"><label>Email</label><input id="email" type="email"></div>
      <div class="field full"><label>Address / Project *</label><textarea id="address" required><?= $q('address') ?></textarea></div>
      <div class="field full"><label>Service engineer</label><input id="engineer" value="<?= $q('engineer') ?>"></div>
    </div>
  </section>

  <section class="machine-toolbar">
    <div><h2>Outdoor Machine Reports <span class="report-count" id="reportCount">1 report</span></h2><p>Add one complete report for every 10 HP, 12 HP, or other outdoor machine.</p></div>
    <button class="btn primary" type="button" onclick="addMachineReport()">+ Add Another Machine Report</button>
  </section>
  <div id="machineReports"></div>
  <div class="bottom-add"><button class="btn primary" type="button" onclick="addMachineReport()">+ Add Another Machine Report</button></div>

  <details class="calc-guide" open><summary>Calculation instructions and Table A reference</summary><div class="calc-body"><div class="formula"><b>Pipe quantity:</b> Length (Rmt) &times; Factor (kg/m)<br><b>Pipe quantity subtotal:</b> Sum of all pipe quantities<br><b>Diversity / Connection Ratio:</b> (Total IDU capacity &divide; (ODU HP &times; 25)) &times; 100<br><b>Total additional refrigerant:</b> Pipe quantity subtotal + Table A addition</div><div class="table-wrap"><table class="reference-table"><thead><tr><th>Maximum liquid pipe length</th><th>Connection ratio (CR)</th><th>6&ndash;8 HP</th><th>10&ndash;12 HP</th><th>14&ndash;18 HP</th><th>20 HP</th></tr></thead><tbody><tr><td rowspan="4">30 m or less</td><td>50% &le; CR &lt; 105%</td><td>0</td><td>0</td><td>0</td><td>0.5</td></tr><tr><td>105% &le; CR &lt; 130%</td><td>0.5</td><td>0.5</td><td>0.5</td><td>1.0</td></tr><tr><td>130% &le; CR &lt; 160%</td><td>0.5</td><td>0.5</td><td>0.5</td><td>1.3</td></tr><tr><td>160% &le; CR &lt; 200%</td><td>0.5</td><td>0.7</td><td>1.0</td><td>1.5</td></tr><tr><td rowspan="6">More than 30 m</td><td>50% &le; CR &lt; 70%</td><td>0</td><td>0</td><td>0</td><td>0.5</td></tr><tr><td>70% &le; CR &lt; 85%</td><td>0.3</td><td>0.5</td><td>0.5</td><td>1.0</td></tr><tr><td>85% &le; CR &lt; 105%</td><td>0.7</td><td>1.0</td><td>1.0</td><td>1.5</td></tr><tr><td>105% &le; CR &lt; 130%</td><td>1.2</td><td>1.5</td><td>1.5</td><td>2.0</td></tr><tr><td>130% &le; CR &lt; 160%</td><td>1.2</td><td>1.5</td><td>1.5</td><td>2.3</td></tr><tr><td>160% &le; CR &lt; 200%</td><td>1.2</td><td>1.7</td><td>2.0</td><td>2.5</td></tr></tbody></table></div></div></details>

  <section class="card"><div class="card-head"><h2>Or upload completed workbook</h2></div><div class="card-body"><div class="choice"><p><b>Already completed the Excel reports?</b></p><p class="hint">Upload .xls or .xlsx instead of using generated reports.</p><button class="btn primary" type="button" onclick="document.getElementById('upload').click()">Choose Excel File</button><input id="upload" type="file" accept=".xls,.xlsx" onchange="uploadWorkbook(this.files)"></div><div id="saved" class="saved"></div></div></section>
</main>

<script>
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const query=new URLSearchParams(location.search);
const storageKey='pmsPreCommissioning:'+query.get('project');
const flatIndex=Number(query.get('flatIndex'));
const defaultSystem=query.get('system')||'';
const pipeFactors=[
  ['6.35 (1/4\")',.022],['9.52 (3/8\")',.057],['12.7 (1/2\")',.11],['15.9 (5/8\")',.17],['19.1 (3/4\")',.26],['22.2 (7/8\")',.36],
  ['25.4 (1\")',''],['28.6 (1 1/8\")',''],['31.8 (1 1/4\")',''],['34.9 (1 3/8\")',''],['38.1 (1 1/2\")',''],['41.3 (1 5/8\")',''],['44.5 (1 3/4\")',''],['47.6 (1 7/8\")',''],['50.8 (2\")','']
];

function machineOf(node){return node.classList&&node.classList.contains('machine-report')?node:node.closest('.machine-report')}
function addMachineReport(data={}){
  const machine=document.createElement('article');
  machine.className='machine-report';
  machine.innerHTML=`
    <div class="machine-banner"><h2 class="machine-title">Machine Report</h2><button class="btn remove-machine" type="button" onclick="removeMachineReport(this)">Remove Report</button></div>
    <section class="card system-card"><div class="card-head"><h3>Machine / System Details</h3><span class="hint">One outdoor machine per report</span></div><div class="card-body grid"><div class="field"><label>System / Capacity *</label><input class="m-system" value="${esc(data.system||data.gasSystem||defaultSystem)}" placeholder="e.g. 10 HP or 12 HP"></div><div class="field"><label>ODU Model *</label><input class="m-odu-model" value="${esc(data.oduModel||(data.odus&&data.odus[0]?.model)||'')}" placeholder="e.g. RXMQ10BRY16"></div><div class="field"><label>ODU Serial No. *</label><input class="m-odu-serial" value="${esc(data.oduSerial||(data.odus&&data.odus[0]?.serial)||'')}" placeholder="Serial number"></div><div class="field"><label>Refrigerant amount</label><input class="m-refrigerant" value="Standard 8 Kg + additional 5.15 Kg = 13.15 Kg" readonly></div></div></section>
    <section class="card"><div class="card-head"><h3>1. Commissioning Equipment Schedule</h3><span class="hint">Models connected to this outdoor machine</span></div><div class="card-body table-wrap"><table><thead><tr><th>#</th><th>Model No. *</th><th>Serial No. *</th><th>System Name *</th><th>Invoice No.</th><th>Invoice Date</th><th></th></tr></thead><tbody class="m-units"></tbody></table><button class="btn add" type="button" onclick="addUnit(this)">+ Add Unit</button></div><div class="card-body field"><label>Findings</label><textarea class="m-findings"></textarea></div></section>
    <section class="card"><div class="card-head"><h3>2. Pressure Testing Report</h3><span class="hint">Gas and liquid readings for this machine</span></div><div class="card-body table-wrap"><table><thead><tr><th>Reading</th><th>Type</th><th>Date</th><th>Time</th><th>Temp. &deg;C</th><th>Pressure PSI</th><th>Remarks</th></tr></thead><tbody class="m-pressure"></tbody></table></div></section>
    <section class="card"><div class="card-head"><h3>3. Additional Refrigerant Gas Quantity</h3><span class="hint">Calculated separately for this machine</span></div><div class="card-body table-wrap"><table><thead><tr><th>Liquid Pipe Size (mm)</th><th>Length (Rmt)</th><th>Factor (kg/m)</th><th>Quantity (kg)</th></tr></thead><tbody class="m-pipes"></tbody><tfoot><tr class="total-row"><th>Total pipe length</th><th class="m-length-total total-value">0.00 Rmt</th><th>Pipe quantity subtotal</th><th class="m-pipe-total total-value">0.00 Kg</th></tr><tr><th colspan="3">Table A addition (kg)</th><th><input class="m-table-a" type="number" step="0.01" value="${Number(data.tableA??1.5)}" oninput="calcMachine(this)"></th></tr><tr class="total-row"><th colspan="3">Total additional refrigerant</th><th class="m-gas-total total-value">1.50 Kg</th></tr></tfoot></table></div></section>
    <section class="card"><div class="card-head"><h3>Sign-off</h3></div><div class="card-body sig-grid"><div class="sig">Service Engineer &ndash; Dealer</div><div class="sig">Service Engineer &ndash; Daikin</div><div class="sig">Customer &ndash; Signature &amp; Stamp</div><div class="sig">Consultant &ndash; Signature</div></div></section>`;
  $('machineReports').appendChild(machine);
  const units=(data.units&&data.units.length)?data.units:[{}]; units.forEach(v=>addUnit(machine,v));
  addPressureRows(machine,data.pressure||[]);
  addPipeRows(machine,data.pipes||[]);
  machine.querySelector('.m-findings').value=data.findings||'';
  calcMachine(machine);
  renumberReports();
  if(arguments.length===0)machine.scrollIntoView({behavior:'smooth',block:'start'});
}
function removeMachineReport(button){if(document.querySelectorAll('.machine-report').length<=1){alert('At least one machine report is required.');return}machineOf(button).remove();renumberReports()}
function renumberReports(){const list=[...document.querySelectorAll('.machine-report')];list.forEach((m,i)=>m.querySelector('.machine-title').textContent='Machine Report '+(i+1));$('reportCount').textContent=list.length+' report'+(list.length===1?'':'s');document.querySelectorAll('.remove-machine').forEach(b=>b.disabled=list.length===1)}
function addUnit(source,v={}){const machine=machineOf(source);const tr=document.createElement('tr');tr.innerHTML=`<td class="unit-num"></td><td><input class="unit-model" value="${esc(v.model)}"></td><td><input class="unit-serial" value="${esc(v.serial)}"></td><td><input class="unit-name" value="${esc(v.systemName)}"></td><td><input class="unit-invoice" value="${esc(v.invoice)}"></td><td><input class="unit-date" type="date" value="${esc(v.invoiceDate)}"></td><td><button class="row-btn" type="button" onclick="removeUnit(this)">&times;</button></td>`;machine.querySelector('.m-units').appendChild(tr);renumberUnits(machine)}
function removeUnit(button){const machine=machineOf(button);if(machine.querySelectorAll('.m-units tr').length<=1){alert('At least one equipment row is required.');return}button.closest('tr').remove();renumberUnits(machine)}
function renumberUnits(machine){[...machine.querySelectorAll('.m-units tr')].forEach((r,i)=>r.querySelector('.unit-num').textContent=i+1)}
function addPressureRows(machine,values){[['Initial','Gas'],['Initial','Liquid'],['Final','Gas'],['Final','Liquid']].forEach((x,i)=>{const v=values[i]||{};const tr=document.createElement('tr');tr.innerHTML=`<td>${x[0]}</td><td>${x[1]}</td><td><input class="p-date" type="date" value="${esc(v.date)}"></td><td><input class="p-time" type="time" value="${esc(v.time)}"></td><td><input class="p-temp" type="number" value="${esc(v.temp??30)}"></td><td><input class="p-psi" type="number" value="${esc(v.psi??580)}"></td><td><input class="p-remarks" value="${esc(v.remarks??'HOLD')}"></td>`;machine.querySelector('.m-pressure').appendChild(tr)})}
function addPipeRows(machine,values){pipeFactors.forEach((x,i)=>{const v=values[i]||{};const tr=document.createElement('tr');tr.innerHTML=`<td class="pipe-size">${x[0]}</td><td><input class="pipe-length" type="number" min="0" step="0.01" value="${esc(v.length??'')}" oninput="calcMachine(this)"></td><td><input class="pipe-factor" type="number" min="0" step="0.001" value="${esc(v.factor??x[1])}" oninput="calcMachine(this)" placeholder="Enter factor"></td><td class="pipe-qty">0.00</td>`;machine.querySelector('.m-pipes').appendChild(tr)})}
function calcMachine(source){const machine=machineOf(source);let length=0,quantity=0;machine.querySelectorAll('.m-pipes tr').forEach(r=>{const len=+r.querySelector('.pipe-length').value||0;const q=len*(+r.querySelector('.pipe-factor').value||0);r.querySelector('.pipe-qty').textContent=q.toFixed(2);length+=len;quantity+=q});machine.querySelector('.m-length-total').textContent=length.toFixed(2)+' Rmt';machine.querySelector('.m-pipe-total').textContent=quantity.toFixed(2)+' Kg';machine.querySelector('.m-gas-total').textContent=(quantity+(+machine.querySelector('.m-table-a').value||0)).toFixed(2)+' Kg'}
function collectMachine(machine){const pipes=[...machine.querySelectorAll('.m-pipes tr')].map(r=>({size:r.querySelector('.pipe-size').textContent,length:+r.querySelector('.pipe-length').value||0,factor:+r.querySelector('.pipe-factor').value||0,quantity:+r.querySelector('.pipe-qty').textContent||0}));const oduModel=machine.querySelector('.m-odu-model').value.trim(),oduSerial=machine.querySelector('.m-odu-serial').value.trim(),system=machine.querySelector('.m-system').value.trim();return{system,gasSystem:system,oduModel,oduSerial,odus:[{model:oduModel,serial:oduSerial}],refrigerant:'Standard 8 Kg + additional 5.15 Kg = 13.15 Kg',findings:machine.querySelector('.m-findings').value.trim(),tableA:+machine.querySelector('.m-table-a').value||0,units:[...machine.querySelectorAll('.m-units tr')].map(r=>({model:r.querySelector('.unit-model').value.trim(),serial:r.querySelector('.unit-serial').value.trim(),systemName:r.querySelector('.unit-name').value.trim(),invoice:r.querySelector('.unit-invoice').value.trim(),invoiceDate:r.querySelector('.unit-date').value})),pressure:[...machine.querySelectorAll('.m-pressure tr')].map(r=>({reading:r.cells[0].textContent,type:r.cells[1].textContent,date:r.querySelector('.p-date').value,time:r.querySelector('.p-time').value,temp:r.querySelector('.p-temp').value,psi:r.querySelector('.p-psi').value,remarks:r.querySelector('.p-remarks').value.trim()})),pipes,totalLength:pipes.reduce((s,p)=>s+p.length,0),pipeSubtotal:pipes.reduce((s,p)=>s+p.quantity,0),totalGas:parseFloat(machine.querySelector('.m-gas-total').textContent)||0}}
function collect(){const shared={date:$('date').value,customer:$('customer').value.trim(),contact:$('contact').value.trim(),address:$('address').value.trim(),email:$('email').value.trim(),engineer:$('engineer').value.trim()};const machineReports=[...document.querySelectorAll('.machine-report')].map(collectMachine);return{...shared,machineReports,...(machineReports[0]||{}),createdAt:new Date().toISOString()}}
function valid(r){if(!r.date||!r.customer||!r.address){alert('Complete date, customer and address.');return false}for(let i=0;i<r.machineReports.length;i++){const m=r.machineReports[i],n=i+1;if(!m.system||!m.oduModel||!m.oduSerial){alert('Complete system, ODU model and ODU serial for Machine Report '+n+'.');return false}if(!m.units.length||m.units.some(u=>!u.model||!u.serial||!u.systemName)){alert('Complete every equipment row in Machine Report '+n+'.');return false}}return true}
function updateDailyDraft(report,file){let draft={};try{draft=JSON.parse(localStorage.getItem('vakhariaSiteVisitDraft')||'{}')||{}}catch(e){}const apply=target=>{target.preCommissioningReport=report||null;target.preCommissioningFile=file||null};if(Number.isInteger(flatIndex)&&flatIndex>=0&&Array.isArray(draft.flats)&&draft.flats[flatIndex])apply(draft.flats[flatIndex]);if(!Number.isInteger(flatIndex)||flatIndex<0||draft.activeFlat===flatIndex)apply(draft);localStorage.setItem('vakhariaSiteVisitDraft',JSON.stringify(draft))}
function returnToDaily(){window.location.href='./'}
function saveReport(){const r=collect();if(!valid(r))return;localStorage.setItem(storageKey,JSON.stringify(r));updateDailyDraft(r,null);$('saved').textContent=r.machineReports.length+' report(s) saved. Returning to daily report...';$('saved').classList.add('show');setTimeout(returnToDaily,500)}
function uploadWorkbook(files){const f=files&&files[0];if(!f)return;if(!/\.(xls|xlsx)$/i.test(f.name)){alert('Select an .xls or .xlsx file.');return}if(f.size>10*1024*1024){alert('Excel file must be 10 MB or smaller.');return}const reader=new FileReader();reader.onload=()=>{const file={name:f.name,mimeType:f.type||'application/vnd.ms-excel',base64:String(reader.result).split(',')[1]||''};updateDailyDraft(null,file);$('saved').textContent=f.name+' attached. Returning to daily report...';$('saved').classList.add('show');setTimeout(returnToDaily,500)};reader.readAsDataURL(f)}
function machineSheet(m,i){const units=m.units.map((u,n)=>`<tr><td>${n+1}</td><td>${esc(u.model)}</td><td>${esc(u.serial)}</td><td>${esc(u.systemName)}</td><td>${esc(u.invoice)}</td><td>${esc(u.invoiceDate)}</td></tr>`).join('');const pressure=m.pressure.map(x=>`<tr><td>${x.reading}</td><td>${x.type}</td><td>${x.date}</td><td>${x.time}</td><td>${x.temp}</td><td>${x.psi}</td><td>${esc(x.remarks)}</td></tr>`).join('');const pipes=m.pipes.map(x=>`<tr><td>${x.size}</td><td>${x.length}</td><td>${x.factor}</td><td>${x.quantity.toFixed(2)}</td></tr>`).join('');return `<h2>Machine Report ${i+1} - ${esc(m.system)}</h2><table border="1"><tr><td>ODU Model</td><td>${esc(m.oduModel)}</td><td>ODU Serial</td><td>${esc(m.oduSerial)}</td></tr></table><h3>Commissioning Equipment Schedule</h3><table border="1"><tr><th>#</th><th>Model No.</th><th>Serial No.</th><th>System Name</th><th>Invoice No.</th><th>Date</th></tr>${units}<tr><td>Refrigerant amount</td><td colspan="5">${esc(m.refrigerant)}</td></tr><tr><td>Findings</td><td colspan="5">${esc(m.findings)}</td></tr></table><h3>Pressure Testing Report</h3><table border="1"><tr><th>Reading</th><th>Type</th><th>Date</th><th>Time</th><th>Temp C</th><th>Pressure PSI</th><th>Remarks</th></tr>${pressure}</table><h3>Additional Refrigerant Gas Quantity</h3><table border="1"><tr><th>Size</th><th>Length Rmt</th><th>Factor</th><th>Quantity Kg</th></tr>${pipes}<tr><th>Total pipe length</th><th>${m.totalLength.toFixed(2)} Rmt</th><th>Pipe quantity subtotal</th><th>${m.pipeSubtotal.toFixed(2)} Kg</th></tr><tr><th colspan="3">Table A addition</th><th>${m.tableA.toFixed(2)} Kg</th></tr><tr><th colspan="3">Total additional</th><th>${m.totalGas.toFixed(2)} Kg</th></tr></table><br>`}
function downloadExcel(){const r=collect();if(!valid(r))return;const shared=`<table border="1"><tr><th colspan="4">Pre-Commissioning Reports</th></tr><tr><td>Date</td><td>${r.date}</td><td>Customer</td><td>${esc(r.customer)}</td></tr><tr><td>Address</td><td colspan="3">${esc(r.address)}</td></tr><tr><td>Contact</td><td>${esc(r.contact)}</td><td>Email</td><td>${esc(r.email)}</td></tr></table>`;const html=`<html><head><meta charset="utf-8"></head><body>${shared}${r.machineReports.map(machineSheet).join('')}</body></html>`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'application/vnd.ms-excel'}));a.download='Pre-Commissioning_Reports_'+(r.customer||'Project').replace(/[^a-z0-9]+/gi,'_')+'.xls';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function restore(r){if(!r)return;['date','customer','contact','address','email','engineer'].forEach(k=>{if(r[k]!==undefined&&$(k))$(k).value=r[k]});$('machineReports').innerHTML='';const reports=(r.machineReports&&r.machineReports.length)?r.machineReports:[r];reports.forEach(addMachineReport)}
$('date').value=new Date().toISOString().slice(0,10);let saved=null;try{saved=JSON.parse(localStorage.getItem(storageKey)||'null')}catch(e){}if(saved)restore(saved);else addMachineReport({system:defaultSystem});
</script>
</body>
</html>
